/**
 * Adds calendar months in UTC, keeping the time of day. A day the target month
 * does not have is clamped to that month's last day (31 Jan + 1 month → 28 Feb).
 */
export function addMonths(value: IsoTimestamp, months: number): IsoTimestamp {
  const date = parseIso(value);
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  const result = new Date(date.getTime());
  result.setUTCFullYear(year, month, Math.min(date.getUTCDate(), lastDay));
  return toIsoTimestamp(result);
}

