/**
 * Billing period arithmetic and proration. Pure functions: no I/O, no clock
 * reads, so the renewal job and the mid-period changes compute the same numbers.
 */
import { addMonths, parseIso } from "@/lib/date";
import type { BillingInterval } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export type PeriodCharge = {
  readonly amountCents: number;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
};

/** Months covered by one period of `interval`. */
export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** The end of the period that starts at `start` and runs for one `interval`. */
export function periodEndAfter(
  start: IsoTimestamp,
  interval: BillingInterval,
): IsoTimestamp {
  return addMonths(start, monthsIn(interval));
}

/** The full charge for one period: price per seat per month × seats × months. */
export function fullPeriodCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  months: number,
): number {
  return priceCentsPerSeatMonthly * seats * months;
}

/** Whole or started days from `at` to `periodEnd`; none once the end is reached. */
export function daysLeft(periodEnd: IsoTimestamp, at: Date): number {
  const remainingMs = parseIso(periodEnd).getTime() - at.getTime();
  return remainingMs > 0 ? Math.ceil(remainingMs / MS_PER_DAY) : 0;
}

/** Whole days between a period's start and end, rounded, and at least one. */
export function daysInPeriod(
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): number {
  const spanMs = parseIso(periodEnd).getTime() - parseIso(periodStart).getTime();
  return Math.max(1, Math.round(spanMs / MS_PER_DAY));
}

/**
 * The share of `fullCents` that covers the rest of the period from `at`: scaled
 * by the days left over the days in the period, rounded down to whole cents.
 */
export function prorateCents(
  fullCents: number,
  period: { readonly start: IsoTimestamp; readonly end: IsoTimestamp },
  at: Date,
): number {
  const total = daysInPeriod(period.start, period.end);
  const left = Math.min(daysLeft(period.end, at), total);
  return Math.floor((fullCents * left) / total);
}

/** A charge for `amountCents` over the given period, or `null` when nothing is owed. */
export function chargeFor(
  amountCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): PeriodCharge | null {
  return amountCents > 0 ? { amountCents, periodStart, periodEnd } : null;
}

