/**
 * Invoice history for the billing page.
 */
import { and, count, desc, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { invoices } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvoice } from "./_mappers";
import type { Tx } from "@/server/db";
import type { Invoice } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

/** What an invoice bills: the amount and the period it covers. */
export type NewInvoice = {
  readonly amountCents: number;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
};

export async function listInvoices(
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  const rows = getDb()
    .select()
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .orderBy(desc(invoices.periodStart))
    .all();
  return rows.map(toInvoice);
}

/**
 * Writes an invoice inside the caller's transaction, so it commits or rolls back
 * with the subscription change it bills for. The number is the next in the
 * workspace's sequence (`INV-0001`, `INV-0002`, …); the unique index on
 * `(org_id, number)` rejects any duplicate.
 */
export function insertInvoice(
  tx: Tx,
  orgId: OrgId,
  invoice: NewInvoice,
): Invoice {
  const issued = tx
    .select({ value: count() })
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .get();
  const sequence = (issued?.value ?? 0) + 1;

  const stamp = toIsoTimestamp(new Date());
  const row = tx
    .insert(invoices)
    .values({
      id: newId(),
      orgId,
      number: `INV-${String(sequence).padStart(4, "0")}`,
      amountCents: invoice.amountCents,
      currency: "usd",
      periodStart: invoice.periodStart,
      periodEnd: invoice.periodEnd,
      paidAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvoice(row);
}

export async function findInvoice(
  orgId: OrgId,
  invoiceId: string,
): Promise<Invoice | null> {
  const row = getDb()
    .select()
    .from(invoices)
    .where(and(orgPredicate(invoices.orgId, orgId), eq(invoices.id, invoiceId)))
    .get();
  return row ? toInvoice(row) : null;
}

