/**
 * Subscription rows; one active row per organization.
 */
import { and, asc, eq, gt, isNotNull, lte, ne } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, organizations, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { toInvoice, toSubscription } from "./_mappers";
import { insertInvoice } from "./invoice-repository";
import type { NewInvoice } from "./invoice-repository";
import type {
  BillingInterval,
  Invoice,
  PlanId,
  Subscription,
  SubscriptionStatus,
} from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

/** Columns a billing change may write. Omitted keys keep their stored value. */
export type SubscriptionWrite = {
  readonly plan?: PlanId;
  readonly interval?: BillingInterval;
  readonly status?: SubscriptionStatus;
  readonly seats?: number;
  readonly currentPeriodStart?: IsoTimestamp;
  readonly currentPeriodEnd?: IsoTimestamp;
  readonly cancelAt?: IsoTimestamp | null;
};

/** The write lands only while every field given here still matches the stored row. */
export type SubscriptionGuard = {
  readonly status?: SubscriptionStatus;
  readonly currentPeriodEnd?: IsoTimestamp;
  readonly cancelAt?: IsoTimestamp;
};

export type SubscriptionCommit = {
  readonly subscription: Subscription;
  readonly invoice: Invoice | null;
};

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const periodEnd = toIsoTimestamp(
    new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY),
  );

  const row = getDb()
    .insert(subscriptions)
    .values({
      id: newId(),
      orgId,
      plan,
      interval,
      status: plan === "free" ? "active" : "trialing",
      seats: 1,
      currentPeriodStart: stamp,
      currentPeriodEnd: periodEnd,
      cancelAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toSubscription(row);
}

/** A plan change ends the trial: the org has made a deliberate choice. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status: "active", updatedAt: stamp })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
export async function cancelSubscription(
  orgId: OrgId,
  cancelAt: IsoTimestamp | null,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      cancelAt,
      status: cancelAt === null ? "active" : "canceled",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * Applies one billing change and, when it carries a charge, the invoice for it,
 * in a single transaction: either both land or neither does. Returns `null`
 * when the guard no longer holds, which means another run already made the change.
 */
export async function commitSubscription(
  orgId: OrgId,
  write: SubscriptionWrite,
  options: { readonly guard?: SubscriptionGuard; readonly invoice?: NewInvoice } = {},
): Promise<SubscriptionCommit | null> {
  const guard = options.guard ?? {};
  const conditions = [orgPredicate(subscriptions.orgId, orgId)];
  if (guard.status !== undefined) {
    conditions.push(eq(subscriptions.status, guard.status));
  }
  if (guard.currentPeriodEnd !== undefined) {
    conditions.push(eq(subscriptions.currentPeriodEnd, guard.currentPeriodEnd));
  }
  if (guard.cancelAt !== undefined) {
    conditions.push(eq(subscriptions.cancelAt, guard.cancelAt));
  }

  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({ ...write, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(...conditions))
      .returning()
      .get();

    if (!row) return null;

    const invoice = options.invoice
      ? insertInvoice(tx, orgId, options.invoice)
      : null;
    return { subscription: toSubscription(row), invoice };
  });
}

/**
 * One page of subscriptions belonging to live (not archived) workspaces, in id
 * order. Cross-tenant by design: the renewal job sweeps every org.
 */
export async function listLiveSubscriptions(
  afterId: string | null,
  limit: number,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        afterId === null ? undefined : gt(subscriptions.id, afterId),
        livePredicate(organizations.archivedAt, {}),
      ),
    )
    .orderBy(asc(subscriptions.id))
    .limit(limit)
    .all();

  return rows.map(({ subscription }) => toSubscription(subscription));
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}

