import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { toInvoice, toSubscription } from "./_mappers";
import { insertInvoice } from "./invoice-repository";
import type { NewInvoice } from "./invoice-repository";
import type {
  BillingInterval,
  Invoice,
  PlanId,
  Subscription,
  SubscriptionStatus,
} from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

/** Columns a billing change may write. Omitted keys keep their stored value. */
export type SubscriptionWrite = {
  readonly plan?: PlanId;
  readonly interval?: BillingInterval;
  readonly status?: SubscriptionStatus;
  readonly seats?: number;
  readonly currentPeriodStart?: IsoTimestamp;
  readonly currentPeriodEnd?: IsoTimestamp;
  readonly cancelAt?: IsoTimestamp | null;
};

/** The write lands only while every field given here still matches the stored row. */
export type SubscriptionGuard = {
  readonly status?: SubscriptionStatus;
  readonly currentPeriodEnd?: IsoTimestamp;
  readonly cancelAt?: IsoTimestamp;
};

export type SubscriptionCommit = {
  readonly subscription: Subscription;
  readonly invoice: Invoice | null;
};

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
