 * What switching to `plan` writes and bills. A trial bills nothing and keeps its
 * period, so its first invoice comes when it ends. Leaving the free plan starts a
 * fresh period at `now`, invoiced in full. Between paid plans, an upgrade bills
 * the price difference for the rest of the current period, and only while
 * active. A downgrade, the same plan or a move to free bills nothing and keeps
 * the period.
 */
function planChange(
  subscription: Subscription,
  plan: PlanId,
  interval: BillingInterval,
  now: Date,
): PlanChange {
  const settled = { plan, interval, status: "active" as const };

  if (
    subscription.status === "trialing" ||
    plan === subscription.plan ||
    plan === "free"
  ) {
    return { write: settled, invoice: null };
  }

  if (subscription.plan === "free") {
    const start = toIsoTimestamp(now);
    const end = periodEndAfter(start, interval);
    const amountCents = fullPeriodCents(
      getPlanLimits(plan).priceCentsPerSeatMonthly,
      subscription.seats,
      monthsIn(interval),
    );
    return {
      write: { ...settled, currentPeriodStart: start, currentPeriodEnd: end },
      invoice: chargeFor(amountCents, start, end),
    };
  }

  const upliftPerSeat =
    getPlanLimits(plan).priceCentsPerSeatMonthly -
    getPlanLimits(subscription.plan).priceCentsPerSeatMonthly;
  const invoice =
    subscription.status === "active" && upliftPerSeat > 0
      ? partialPeriodCharge(subscription, upliftPerSeat, subscription.seats, now)
      : null;

  return { write: settled, invoice };
}

/** Mid-period changes are billed only on an active paid subscription. */
function isActivePaid(subscription: Subscription): boolean {
  return subscription.status === "active" && subscription.plan !== "free";
}

/** What `seats` more units at `priceCentsPerSeatMonthly` cost for the rest of the current period. */
function partialPeriodCharge(
  subscription: Subscription,
  priceCentsPerSeatMonthly: number,
  seats: number,
  at: Date,
): NewInvoice | null {
  const amountCents = prorateCents(
    fullPeriodCents(priceCentsPerSeatMonthly, seats, monthsIn(subscription.interval)),
    { start: subscription.currentPeriodStart, end: subscription.currentPeriodEnd },
    at,
  );
  return chargeFor(
    amountCents,
    subscription.currentPeriodStart,
    subscription.currentPeriodEnd,
  );
}

/** Writes a billing change and, when it carries a charge, issues and announces its invoice. */
async function commitBilling(
  orgId: OrgId,
  write: SubscriptionWrite,
  invoice: NewInvoice | null,
): Promise<Subscription> {
  const commit = await subscriptionRepo.commitSubscription(orgId, write, {
    invoice: invoice ?? undefined,
  });
  if (commit === null) {
    throw new Error(`Subscription for org ${orgId} not found`);
  }
  if (commit.invoice) await announceInvoice(commit.invoice);
  return commit.subscription;
}

