/**
 * Period arithmetic and proration: calendar months, days left, rounding.
 */
import { describe, expect, it } from "vitest";
import {
  chargeFor,
  daysInPeriod,
  daysLeft,
  fullPeriodCents,
  periodEndAfter,
  prorateCents,
} from "@/lib/billing-periods";
import { addMonths } from "@/lib/date";
import { toIsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

describe("addMonths", () => {
  it("clamps a day the target month lacks to its last day", () => {
    expect(addMonths(toIsoTimestamp("2027-01-31T10:00:00.000Z"), 1)).toBe(
      "2027-02-28T10:00:00.000Z",
    );
  });

  it("ends an annual period on the same day of the following year, clamped from 29 February", () => {
    expect(addMonths(toIsoTimestamp("2028-02-29T00:00:00.000Z"), 12)).toBe(
      "2029-02-28T00:00:00.000Z",
    );
  });

  it("carries a clamped day forward from the previous period's end", () => {
    const february = addMonths(toIsoTimestamp("2027-01-31T10:00:00.000Z"), 1);
    expect(february).toBe("2027-02-28T10:00:00.000Z");
    expect(addMonths(february, 1)).toBe("2027-03-28T10:00:00.000Z");
  });

  it("keeps the time of day across a year boundary", () => {
    expect(addMonths(toIsoTimestamp("2026-12-15T23:59:59.000Z"), 1)).toBe(
      "2027-01-15T23:59:59.000Z",
    );
  });
});

describe("periodEndAfter", () => {
  it("runs a monthly period one month and an annual period twelve", () => {
    const start = toIsoTimestamp("2027-03-10T06:00:00.000Z");
    expect(periodEndAfter(start, "monthly")).toBe("2027-04-10T06:00:00.000Z");
    expect(periodEndAfter(start, "annual")).toBe("2028-03-10T06:00:00.000Z");
  });
});

describe("daysLeft", () => {
  const end = new Date("2027-03-01T00:00:00.000Z");

  it("counts a partly used day as a whole day", () => {
    const at = new Date(end.getTime() - (14 * 24 + 22) * 60 * 60 * 1000);
    expect(daysLeft(toIsoTimestamp(end), at)).toBe(15);
  });

  it("counts nothing once the period end has been reached", () => {
    expect(daysLeft(toIsoTimestamp(end), end)).toBe(0);
    expect(daysLeft(toIsoTimestamp(end), new Date(end.getTime() + DAY_MS))).toBe(0);
  });
});

describe("daysInPeriod", () => {
  it("counts the whole days of the period, and at least one", () => {
    expect(
      daysInPeriod(
        toIsoTimestamp("2027-02-01T00:00:00.000Z"),
        toIsoTimestamp("2027-03-01T00:00:00.000Z"),
      ),
    ).toBe(28);
    expect(
      daysInPeriod(
        toIsoTimestamp("2027-02-01T00:00:00.000Z"),
        toIsoTimestamp("2027-02-01T00:00:00.000Z"),
      ),
    ).toBe(1);
  });
});

describe("prorateCents", () => {
  const period = {
    start: toIsoTimestamp("2027-03-01T00:00:00.000Z"),
    end: toIsoTimestamp("2027-03-31T00:00:00.000Z"),
  };

  it("scales the full amount by the days left over the days in the period", () => {
    const at = new Date("2027-03-16T00:00:00.000Z");
    expect(prorateCents(1_900, period, at)).toBe(950);
  });

  it("rounds down to whole cents", () => {
    const period3 = {
      start: toIsoTimestamp("2027-03-01T00:00:00.000Z"),
      end: toIsoTimestamp("2027-03-04T00:00:00.000Z"),
    };
    expect(prorateCents(1_000, period3, new Date("2027-03-02T00:00:00.000Z"))).toBe(666);
  });

  it("charges nothing once the period has ended", () => {
    expect(prorateCents(1_900, period, period.end ? new Date(period.end) : new Date())).toBe(0);
  });
});

describe("charges", () => {
  it("multiplies price, seats and months", () => {
    expect(fullPeriodCents(900, 3, 12)).toBe(32_400);
  });

  it("produces no charge for zero cents", () => {
    expect(chargeFor(0, toIsoTimestamp("2027-03-01T00:00:00.000Z"), toIsoTimestamp("2027-04-01T00:00:00.000Z"))).toBeNull();
    expect(chargeFor(500, toIsoTimestamp("2027-03-01T00:00:00.000Z"), toIsoTimestamp("2027-04-01T00:00:00.000Z"))).toEqual({
      amountCents: 500,
      periodStart: "2027-03-01T00:00:00.000Z",
      periodEnd: "2027-04-01T00:00:00.000Z",
    });
  });
});

