/**
 * The billing renewal job and the mid-period charges: renewal and invoicing,
 * cancellation on its date, replay safety, and proration for seats and plans.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { addMonths } from "@/lib/date";
import { subscribe } from "@/lib/event-bus";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as organizationRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as notificationService from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { BillingInterval, PlanId, SubscriptionStatus } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

const DAY_MS = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = activityService.registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

/** Puts a tenant's subscription into a given period, bypassing the billing flows. */
async function setSubscription(
  tenant: Tenant,
  values: {
    plan: PlanId;
    seats: number;
    periodStart: string;
    periodEnd: string;
    interval?: BillingInterval;
    status?: SubscriptionStatus;
    cancelAt?: string | null;
  },
): Promise<void> {
  await subscriptionRepo.commitSubscription(tenant.org.id, {
    plan: values.plan,
    interval: values.interval ?? "monthly",
    status: values.status ?? "active",
    seats: values.seats,
    currentPeriodStart: toIsoTimestamp(values.periodStart),
    currentPeriodEnd: toIsoTimestamp(values.periodEnd),
    cancelAt: values.cancelAt ? toIsoTimestamp(values.cancelAt) : null,
  });
}

async function subscriptionOf(orgId: OrgId) {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (!subscription) throw new Error(`no subscription for ${orgId}`);
  return subscription;
}

describe("billing renewal", () => {
  it("renews one period per elapsed interval and invoices each paid period in full", async () => {
    const tenant = await createTenant("renew-paid", "growth");
    await setSubscription(tenant, {
      plan: "growth",
      seats: 3,
      periodStart: "2027-01-31T10:00:00.000Z",
      periodEnd: "2027-02-28T10:00:00.000Z",
    });

    const result = await runBillingRenewalJob(new Date("2027-03-30T00:00:00.000Z"));
    expect(result.failed).toBe(0);

    const subscription = await subscriptionOf(tenant.org.id);
    expect(subscription).toMatchObject({
      status: "active",
      plan: "growth",
      seats: 3,
      currentPeriodStart: "2027-03-28T10:00:00.000Z",
      currentPeriodEnd: "2027-04-28T10:00:00.000Z",
    });

    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices.map((invoice) => [invoice.number, invoice.periodStart, invoice.periodEnd, invoice.amountCents, invoice.currency])).toEqual([
      ["INV-0002", "2027-03-28T10:00:00.000Z", "2027-04-28T10:00:00.000Z", 5_700, "usd"],
      ["INV-0001", "2027-02-28T10:00:00.000Z", "2027-03-28T10:00:00.000Z", 5_700, "usd"],
    ]);
    expect(invoices.every((invoice) => invoice.paidAt === null)).toBe(true);
  });

  it("changes nothing when it runs again at the same instant", async () => {
    const tenant = await createTenant("renew-replay", "starter");
    await setSubscription(tenant, {
      plan: "starter",
      seats: 2,
      periodStart: "2027-05-01T00:00:00.000Z",
      periodEnd: "2027-06-01T00:00:00.000Z",
    });
    const now = new Date("2027-06-15T00:00:00.000Z");

    await runBillingRenewalJob(now);
    const afterFirst = await subscriptionOf(tenant.org.id);
    const invoicesAfterFirst = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);

    const again = await runBillingRenewalJob(now);

    expect(again.processed).toBe(0);
    expect(await subscriptionOf(tenant.org.id)).toEqual(afterFirst);
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toEqual(invoicesAfterFirst);
    expect(invoicesAfterFirst).toHaveLength(1);
  });

  it("publishes, audits and announces each invoice exactly once", async () => {
    const tenant = await createTenant("renew-events", "starter");
    await setSubscription(tenant, {
      plan: "starter",
      seats: 2,
      periodStart: "2027-05-01T00:00:00.000Z",
      periodEnd: "2027-06-01T00:00:00.000Z",
    });

    const seen: TaskflowEventMap["billing.invoice_issued"][] = [];
    const off = subscribe("billing.invoice_issued", (payload) => {
      if (payload.orgId === tenant.org.id) seen.push(payload);
    });
    await runBillingRenewalJob(new Date("2027-06-15T00:00:00.000Z"));
    off();

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: null,
      invoiceNumber: "INV-0001",
      amountCents: 1_800,
      periodStart: "2027-06-01T00:00:00.000Z",
      periodEnd: "2027-07-01T00:00:00.000Z",
    });

    const audit = await activityService.listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "billing.invoice_issued",
      subjectKind: "subscription",
      subjectId: tenant.org.id,
      actorId: null,
    });

    const told = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(told.items).toHaveLength(1);

    const notToldAdmin = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(notToldAdmin.items).toHaveLength(0);
  });

  it("leaves trialing and past-due subscriptions alone", async () => {
    const trial = await createTenant("skip-trial", "growth");
    const pastDue = await createTenant("skip-past-due", "growth");
    await setSubscription(pastDue, {
      plan: "growth",
      seats: 2,
      status: "past_due",
      periodStart: "2027-01-01T00:00:00.000Z",
      periodEnd: "2027-02-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2027-03-01T00:00:00.000Z"));

    expect(await subscriptionOf(trial.org.id)).toMatchObject({ status: "trialing", plan: "growth" });
    expect(await subscriptionOf(pastDue.org.id)).toMatchObject({
      status: "past_due",
      currentPeriodEnd: "2027-02-01T00:00:00.000Z",
    });
    expect(
      await billingService.listInvoices(pastDue.actors.owner, pastDue.org.id),
    ).toHaveLength(0);
  });

  it("skips archived workspaces entirely", async () => {
    const tenant = await createTenant("archived-org", "growth");
    await setSubscription(tenant, {
      plan: "growth",
      seats: 2,
      periodStart: "2027-01-01T00:00:00.000Z",
      periodEnd: "2027-02-01T00:00:00.000Z",
    });
    await organizationRepo.archiveOrg(tenant.org.id);

    await runBillingRenewalJob(new Date("2027-03-01T00:00:00.000Z"));

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      currentPeriodEnd: "2027-02-01T00:00:00.000Z",
    });
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
  });

  it("reaches every workspace, however many there are", async () => {
    const count = 120;
    const orgIds: OrgId[] = [];
    for (let index = 0; index < count; index += 1) {
      const tenant = await createTenant(`bulk-${index}`, "starter");
      await setSubscription(tenant, {
        plan: "starter",
        seats: 1,
        periodStart: "2027-01-01T00:00:00.000Z",
        periodEnd: "2027-02-01T00:00:00.000Z",
      });
      orgIds.push(tenant.org.id);
    }

    const result = await runBillingRenewalJob(new Date("2027-03-15T00:00:00.000Z"));
    expect(result.failed).toBe(0);
    expect(result.processed).toBeGreaterThanOrEqual(count);

    for (const orgId of orgIds) {
      expect(await subscriptionOf(orgId)).toMatchObject({
        currentPeriodEnd: "2027-04-01T00:00:00.000Z",
      });
      expect(
        (await billingService.listInvoices(
          { userId: "u", orgId, role: "owner" } as never,
          orgId,
        )).length,
      ).toBe(1);
    }
  });

  it("ends a cancellation on its date: the workspace moves to free and nothing is invoiced", async () => {
    const tenant = await createTenant("cancel-date", "growth");
    await setSubscription(tenant, {
      plan: "growth",
      seats: 4,
      status: "canceled",
      periodStart: "2027-01-01T00:00:00.000Z",
      periodEnd: "2027-02-01T00:00:00.000Z",
      cancelAt: "2027-02-01T00:00:00.000Z",
    });

    const seen: TaskflowEventMap["billing.plan_changed"][] = [];
    const off = subscribe("billing.plan_changed", (payload) => {
      if (payload.orgId === tenant.org.id) seen.push(payload);
    });
    await runBillingRenewalJob(new Date("2027-02-10T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2027-02-10T00:00:00.000Z"));
    off();

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2027-02-01T00:00:00.000Z",
      currentPeriodEnd: "2027-03-01T00:00:00.000Z",
    });
    expect(seen).toEqual([
      {
        orgId: tenant.org.id,
        actorId: null,
        occurredAt: "2027-02-01T00:00:00.000Z",
        from: "growth",
        to: "free",
      },
    ]);
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
  });

  it("waits for the cancellation date, even once the period has ended", async () => {
    const tenant = await createTenant("cancel-later", "growth");
    await setSubscription(tenant, {
      plan: "growth",
      seats: 2,
      status: "canceled",
      periodStart: "2027-01-01T00:00:00.000Z",
      periodEnd: "2027-02-01T00:00:00.000Z",
      cancelAt: "2027-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2027-02-10T00:00:00.000Z"));

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "growth",
      status: "canceled",
      currentPeriodEnd: "2027-02-01T00:00:00.000Z",
      cancelAt: "2027-03-01T00:00:00.000Z",
    });
  });
});

describe("mid-period changes", () => {
  /** A 30-day period that started ten days ago, so twenty days remain. */
  function midPeriod(): { periodStart: string; periodEnd: string } {
    const now = Date.now();
    return {
      periodStart: new Date(now - 10 * DAY_MS).toISOString(),
      periodEnd: new Date(now + 20 * DAY_MS).toISOString(),
    };
  }

  it("charges added seats for the rest of the period and nothing for removed seats", async () => {
    const tenant = await createTenant("seats-mid", "growth");
    const period = midPeriod();
    await setSubscription(tenant, { plan: "growth", seats: 4, ...period });

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 6 });

    // 1_900 × 2 seats × 20 of 30 days = 2_533.33 → 2_533
    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 2_533,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
    });
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      seats: 6,
      currentPeriodStart: period.periodStart,
      currentPeriodEnd: period.periodEnd,
    });

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 3 });

    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(1);
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({ seats: 3 });
  });

  it("charges nothing for seat changes during a trial", async () => {
    const tenant = await createTenant("seats-trial", "growth");

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 5 });

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({ seats: 5, status: "trialing" });
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
  });

  it("bills an upgrade's price difference for the rest of the period, and a downgrade nothing", async () => {
    const tenant = await createTenant("plan-mid", "growth");
    const period = midPeriod();
    await setSubscription(tenant, { plan: "growth", seats: 4, ...period });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    // (3_900 − 1_900) × 4 seats × 20 of 30 days = 5_333.33 → 5_333
    const afterUpgrade = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(afterUpgrade).toHaveLength(1);
    expect(afterUpgrade[0]).toMatchObject({
      amountCents: 5_333,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
    });
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "enterprise",
      currentPeriodStart: period.periodStart,
      currentPeriodEnd: period.periodEnd,
    });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(1);
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "starter",
      currentPeriodEnd: period.periodEnd,
    });
  });

  it("starts a fresh period when leaving the free plan, invoiced in full", async () => {
    const tenant = await createTenant("free-to-paid", "free");
    const before = await subscriptionOf(tenant.org.id);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "annual",
    });

    const subscription = await subscriptionOf(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "growth",
      interval: "annual",
      status: "active",
      currentPeriodStart: subscription.currentPeriodStart,
    });
    expect(subscription.currentPeriodEnd).toBe(
      addMonths(subscription.currentPeriodStart, 12),
    );
    expect(new Date(subscription.currentPeriodStart).getTime()).toBeGreaterThanOrEqual(
      new Date(before.currentPeriodStart).getTime(),
    );

    // 1_900 × 1 seat × 12 months
    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 22_800,
      periodStart: subscription.currentPeriodStart,
      periodEnd: subscription.currentPeriodEnd,
    });
  });

  it("charges nothing for moving to the free plan", async () => {
    const tenant = await createTenant("to-free", "growth");
    const period = midPeriod();
    await setSubscription(tenant, { plan: "growth", seats: 4, ...period });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "free",
      interval: "monthly",
    });

    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "free",
      currentPeriodEnd: period.periodEnd,
    });
  });

  it("keeps the trial period when a plan is chosen during the trial; the first invoice comes when it ends", async () => {
    const tenant = await createTenant("trial-choice", "starter");
    const trial = await subscriptionOf(tenant.org.id);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "growth",
      status: "active",
      currentPeriodStart: trial.currentPeriodStart,
      currentPeriodEnd: trial.currentPeriodEnd,
    });
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);

    const dayAfterTrial = new Date(new Date(trial.currentPeriodEnd).getTime() + DAY_MS);
    await runBillingRenewalJob(dayAfterTrial);

    // One seat on growth for the first full month after the trial.
    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 1_900,
      periodStart: trial.currentPeriodEnd,
      periodEnd: addMonths(trial.currentPeriodEnd, 1),
    });
  });
});

