/**
 * The billing renewal job and the mid-period charges: renewal and invoicing,
 * cancellation on its date, replay safety, and proration for seats and plans.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { addMonths } from "@/lib/date";
import { subscribe } from "@/lib/event-bus";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as organizationRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as notificationService from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { BillingInterval, PlanId, SubscriptionStatus } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

const DAY_MS = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = activityService.registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

/** Puts a tenant's subscription into a given period, bypassing the billing flows. */
async function setSubscription(
  tenant: Tenant,
  values: {
    plan: PlanId;
    seats: number;
    periodStart: string;
    periodEnd: string;
    interval?: BillingInterval;
    status?: SubscriptionStatus;
    cancelAt?: string | null;
  },
): Promise<void> {
  await subscriptionRepo.commitSubscription(tenant.org.id, {
    plan: values.plan,
    interval: values.interval ?? "monthly",
    status: values.status ?? "active",
    seats: values.seats,
    currentPeriodStart: toIsoTimestamp(values.periodStart),
    currentPeriodEnd: toIsoTimestamp(values.periodEnd),
    cancelAt: values.cancelAt ? toIsoTimestamp(values.cancelAt) : null,
  });
}

async function subscriptionOf(orgId: OrgId) {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (!subscription) throw new Error(`no subscription for ${orgId}`);
  return subscription;
}

