      orgIds.push(tenant.org.id);
    }

    const result = await runBillingRenewalJob(new Date("2027-03-15T00:00:00.000Z"));
    expect(result.failed).toBe(0);
    expect(result.processed).toBeGreaterThanOrEqual(count);

    for (const orgId of orgIds) {
      expect(await subscriptionOf(orgId)).toMatchObject({
        currentPeriodEnd: "2027-04-01T00:00:00.000Z",
      });
      expect(
        (await billingService.listInvoices(
          { userId: "u", orgId, role: "owner" } as never,
          orgId,
        )).length,
      ).toBe(1);
    }
  });

  it("ends a cancellation on its date: the workspace moves to free and nothing is invoiced", async () => {
    const tenant = await createTenant("cancel-date", "growth");
    await setSubscription(tenant, {
      plan: "growth",
      seats: 4,
      status: "canceled",
      periodStart: "2027-01-01T00:00:00.000Z",
      periodEnd: "2027-02-01T00:00:00.000Z",
      cancelAt: "2027-02-01T00:00:00.000Z",
    });

    const seen: TaskflowEventMap["billing.plan_changed"][] = [];
    const off = subscribe("billing.plan_changed", (payload) => {
      if (payload.orgId === tenant.org.id) seen.push(payload);
    });
    await runBillingRenewalJob(new Date("2027-02-10T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2027-02-10T00:00:00.000Z"));
    off();

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2027-02-01T00:00:00.000Z",
      currentPeriodEnd: "2027-03-01T00:00:00.000Z",
    });
    expect(seen).toEqual([
      {
        orgId: tenant.org.id,
        actorId: null,
        occurredAt: "2027-02-01T00:00:00.000Z",
        from: "growth",
        to: "free",
      },
    ]);
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
  });

  it("waits for the cancellation date, even once the period has ended", async () => {
    const tenant = await createTenant("cancel-later", "growth");
    await setSubscription(tenant, {
      plan: "growth",
      seats: 2,
      status: "canceled",
      periodStart: "2027-01-01T00:00:00.000Z",
      periodEnd: "2027-02-01T00:00:00.000Z",
      cancelAt: "2027-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2027-02-10T00:00:00.000Z"));

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "growth",
      status: "canceled",
      currentPeriodEnd: "2027-02-01T00:00:00.000Z",
      cancelAt: "2027-03-01T00:00:00.000Z",
    });
  });
});

describe("mid-period changes", () => {
  /** A 30-day period that started ten days ago, so twenty days remain. */
  function midPeriod(): { periodStart: string; periodEnd: string } {
    const now = Date.now();
    return {
      periodStart: new Date(now - 10 * DAY_MS).toISOString(),
      periodEnd: new Date(now + 20 * DAY_MS).toISOString(),
    };
  }

  it("charges added seats for the rest of the period and nothing for removed seats", async () => {
    const tenant = await createTenant("seats-mid", "growth");
    const period = midPeriod();
    await setSubscription(tenant, { plan: "growth", seats: 4, ...period });

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 6 });

    // 1_900 × 2 seats × 20 of 30 days = 2_533.33 → 2_533
    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 2_533,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
    });
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      seats: 6,
      currentPeriodStart: period.periodStart,
      currentPeriodEnd: period.periodEnd,
    });

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 3 });

    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(1);
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({ seats: 3 });
  });

  it("charges nothing for seat changes during a trial", async () => {
    const tenant = await createTenant("seats-trial", "growth");

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 5 });

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({ seats: 5, status: "trialing" });
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
  });

  it("bills an upgrade's price difference for the rest of the period, and a downgrade nothing", async () => {
    const tenant = await createTenant("plan-mid", "growth");
    const period = midPeriod();
    await setSubscription(tenant, { plan: "growth", seats: 4, ...period });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    // (3_900 − 1_900) × 4 seats × 20 of 30 days = 5_333.33 → 5_333
    const afterUpgrade = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(afterUpgrade).toHaveLength(1);
    expect(afterUpgrade[0]).toMatchObject({
      amountCents: 5_333,
      periodStart: period.periodStart,
      periodEnd: period.periodEnd,
    });
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "enterprise",
      currentPeriodStart: period.periodStart,
      currentPeriodEnd: period.periodEnd,
    });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(1);
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "starter",
      currentPeriodEnd: period.periodEnd,
    });
  });

  it("starts a fresh period when leaving the free plan, invoiced in full", async () => {
    const tenant = await createTenant("free-to-paid", "free");
    const before = await subscriptionOf(tenant.org.id);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "annual",
    });

    const subscription = await subscriptionOf(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "growth",
      interval: "annual",
      status: "active",
      currentPeriodStart: subscription.currentPeriodStart,
    });
    expect(subscription.currentPeriodEnd).toBe(
      addMonths(subscription.currentPeriodStart, 12),
    );
    expect(new Date(subscription.currentPeriodStart).getTime()).toBeGreaterThanOrEqual(
      new Date(before.currentPeriodStart).getTime(),
    );

    // 1_900 × 1 seat × 12 months
    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 22_800,
      periodStart: subscription.currentPeriodStart,
      periodEnd: subscription.currentPeriodEnd,
    });
  });

  it("charges nothing for moving to the free plan", async () => {
    const tenant = await createTenant("to-free", "growth");
    const period = midPeriod();
    await setSubscription(tenant, { plan: "growth", seats: 4, ...period });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "free",
      interval: "monthly",
    });

    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);
    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "free",
      currentPeriodEnd: period.periodEnd,
    });
  });

  it("keeps the trial period when a plan is chosen during the trial; the first invoice comes when it ends", async () => {
    const tenant = await createTenant("trial-choice", "starter");
    const trial = await subscriptionOf(tenant.org.id);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(await subscriptionOf(tenant.org.id)).toMatchObject({
      plan: "growth",
      status: "active",
      currentPeriodStart: trial.currentPeriodStart,
      currentPeriodEnd: trial.currentPeriodEnd,
    });
    expect(
      await billingService.listInvoices(tenant.actors.owner, tenant.org.id),
    ).toHaveLength(0);

    const dayAfterTrial = new Date(new Date(trial.currentPeriodEnd).getTime() + DAY_MS);
    await runBillingRenewalJob(dayAfterTrial);

    // One seat on growth for the first full month after the trial.
    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 1_900,
      periodStart: trial.currentPeriodEnd,
      periodEnd: addMonths(trial.currentPeriodEnd, 1),
    });
  });
});

