/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const change = planChange(current, input.plan, input.interval, new Date());
  const subscription = await commitBilling(input.orgId, change.write, change.invoice);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: current.plan,
    to: input.plan,
  });

  return subscription;
}

/**
 * Adding seats to an active paid subscription is charged for the seats added,
 * prorated over the rest of the period. Removing seats charges and credits nothing.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const seatLimit = getLimit(subscription.plan, "seats");

  if (input.seats > seatLimit) {
    throw new Error(`Plan ${subscription.plan} tops out at ${seatLimit} seats`);
  }

  const added = input.seats - subscription.seats;
  const invoice =
    isActivePaid(subscription) && added > 0
      ? partialPeriodCharge(
          subscription,
          getPlanLimits(subscription.plan).priceCentsPerSeatMonthly,
          added,
          new Date(),
        )
      : null;

  return commitBilling(input.orgId, { seats: input.seats }, invoice);
}

/** Publishes an issued invoice. The audit log and the owner's notification both listen for it. The actor is never set, so the owner is always the one told. */
export async function announceInvoice(invoice: Invoice): Promise<void> {
  await emit("billing.invoice_issued", {
    orgId: invoice.orgId,
    actorId: null,
    occurredAt: invoice.createdAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });
}

type PlanChange = {
  readonly write: SubscriptionWrite;
  readonly invoice: NewInvoice | null;
};

/**
 * What switching to `plan` writes and bills. A trial bills nothing and keeps its
 * period, so its first invoice comes when it ends. Leaving the free plan starts a
 * fresh period at `now`, invoiced in full. Between paid plans, an upgrade bills
 * the price difference for the rest of the current period, and only while
 * active. A downgrade, the same plan or a move to free bills nothing and keeps
 * the period.
 */
function planChange(
  subscription: Subscription,
  plan: PlanId,
  interval: BillingInterval,
  now: Date,
): PlanChange {
  const settled = { plan, interval, status: "active" as const };

  if (
    subscription.status === "trialing" ||
    plan === subscription.plan ||
    plan === "free"
  ) {
    return { write: settled, invoice: null };
  }

  if (subscription.plan === "free") {
    const start = toIsoTimestamp(now);
