  if (guard.plan !== undefined) {
    conditions.push(eq(subscriptions.plan, guard.plan));
  }
  if (guard.interval !== undefined) {
    conditions.push(eq(subscriptions.interval, guard.interval));
  }
  if (guard.seats !== undefined) {
    conditions.push(eq(subscriptions.seats, guard.seats));
  }
  if (guard.currentPeriodStart !== undefined) {
    conditions.push(eq(subscriptions.currentPeriodStart, guard.currentPeriodStart));
