  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * Applies one billing change and, when it carries a charge, the invoice for it,
 * in a single transaction: either both land or neither does. Returns `null`
 * when the guard no longer holds, which means another run already made the change.
 */
export async function commitSubscription(
  orgId: OrgId,
  write: SubscriptionWrite,
  options: { readonly guard?: SubscriptionGuard; readonly invoice?: NewInvoice } = {},
): Promise<SubscriptionCommit | null> {
  const guard = options.guard ?? {};
  const conditions = [orgPredicate(subscriptions.orgId, orgId)];
  if (guard.status !== undefined) {
    conditions.push(eq(subscriptions.status, guard.status));
  }
  if (guard.currentPeriodEnd !== undefined) {
    conditions.push(eq(subscriptions.currentPeriodEnd, guard.currentPeriodEnd));
  }
  if (guard.cancelAt !== undefined) {
    conditions.push(eq(subscriptions.cancelAt, guard.cancelAt));
  }

  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({ ...write, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(...conditions))
      .returning()
      .get();

    if (!row) return null;

    const invoice = options.invoice
      ? insertInvoice(tx, orgId, options.invoice)
      : null;
    return { subscription: toSubscription(row), invoice };
  });
}

/**
 * One page of subscriptions belonging to live (not archived) workspaces, in id
 * order. Cross-tenant by design: the renewal job sweeps every org.
 */
export async function listLiveSubscriptions(
  afterId: string | null,
  limit: number,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        afterId === null ? undefined : gt(subscriptions.id, afterId),
        livePredicate(organizations.archivedAt, {}),
      ),
    )
    .orderBy(asc(subscriptions.id))
    .limit(limit)
    .all();

  return rows.map(({ subscription }) => toSubscription(subscription));
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}

