 *
 * Must call (do not reimplement): emit, commitSubscription, announceInvoice, chargeFor, fullPeriodCents, monthsIn, periodEndAfter
 */
import { getPlanLimits } from "@/config/plan-limits";
import {
  chargeFor,
  fullPeriodCents,
  monthsIn,
  periodEndAfter,
} from "@/lib/billing-periods";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { announceInvoice } from "@/server/services/billing-service";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

/** Subscriptions read per page; the scan walks every page, however many workspaces exist. */
const PAGE_SIZE = 100;

const logger = createLogger("billing-renewal-job");

/**
 * Brings every live workspace's subscription up to `now`.
 *
 * An `active` subscription whose period has ended is renewed one period at a
 * time, until its period end lies after `now`; a paid plan is invoiced for each
 * new period in full, at the seat count at that moment. A `canceled`
 * subscription whose cancellation date has passed drops to the free plan on that
 * date, with no invoice. `trialing` and `past_due` subscriptions are left alone.
 *
 * Every step is a guarded write, so running again at the same instant finds
 * nothing left to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let afterId: string | null = null;

    for (;;) {
      const page = await subscriptionRepo.listLiveSubscriptions(
        afterId,
        PAGE_SIZE,
      );

      for (const subscription of page) {
        try {
          if (await settle(subscription, now)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      const last = page[page.length - 1];
      if (page.length < PAGE_SIZE || last === undefined) return;
      afterId = last.id;
    }
  });
}

/**
 * Runs every step that is due for one subscription, in order. Returns whether
 * any step ran. A step that loses its guard ends the walk: another run has
 * already taken it.
 */
async function settle(subscription: Subscription, now: Date): Promise<boolean> {
  let current = subscription;
  let changed = false;

  for (;;) {
    const next = await advance(current, now);
    if (next === null) return changed;
    current = next;
    changed = true;
  }
}

/** The one step due next for `subscription`, or `null` when none is. */
async function advance(
  subscription: Subscription,
  now: Date,
): Promise<Subscription | null> {
  if (
    subscription.status === "canceled" &&
    isAtOrBefore(subscription.cancelAt, now)
  ) {
    return endCancellation(subscription);
  }

  if (
    subscription.status === "active" &&
    isAtOrBefore(subscription.currentPeriodEnd, now)
  ) {
    return renewPeriod(subscription);
  }

  return null;
}

/** Renews one period. The next period starts where this one ended; a paid plan is invoiced for it in full. */
async function renewPeriod(
  subscription: Subscription,
): Promise<Subscription | null> {
  const start = subscription.currentPeriodEnd;
  const end = periodEndAfter(start, subscription.interval);
  const amountCents = fullPeriodCents(
    getPlanLimits(subscription.plan).priceCentsPerSeatMonthly,
    subscription.seats,
    monthsIn(subscription.interval),
  );

  const commit = await subscriptionRepo.commitSubscription(
    subscription.orgId,
    { currentPeriodStart: start, currentPeriodEnd: end },
    {
      guard: { status: "active", currentPeriodEnd: start },
      invoice: chargeFor(amountCents, start, end) ?? undefined,
    },
  );
  if (commit === null) return null;

  if (commit.invoice) await announceInvoice(commit.invoice);
  return commit.subscription;
}

/** Ends a cancellation on its date: the workspace moves to free, with a new monthly period starting there. Nothing is invoiced. */
async function endCancellation(
  subscription: Subscription,
): Promise<Subscription | null> {
  const cancelAt = subscription.cancelAt;
  if (cancelAt === null) return null;

  const commit = await subscriptionRepo.commitSubscription(
    subscription.orgId,
    {
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: cancelAt,
      currentPeriodEnd: periodEndAfter(cancelAt, "monthly"),
    },
    { guard: { status: "canceled", cancelAt } },
  );
  if (commit === null) return null;

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: cancelAt,
    from: subscription.plan,
    to: "free",
  });

  return commit.subscription;
}

